    console.log('  Returned fields:', Object.keys(result));
  }, TEST_TIMEOUT);

  test('TC-004: batch-analyze-items processes multiple items', async () => {
    const items = [
      { groupId: 'group-1', primaryPhotoUrl: TEST_PHOTOS.lego },
