    console.log(`  Processed 10 items in ${duration}ms`);
  }, TEST_TIMEOUT * 3);

  test('TC-006: analyze-item-image handles missing photoUrl', async () => {
    const { data, error } = await supabase.functions.invoke('analyze-item-image', {
      body: {
        sellerId: 'test-seller-e2e'
