  test('TC-009: batch-analyze-items partial failure tolerance', async () => {
    const items = [
      { groupId: 'valid-1', primaryPhotoUrl: TEST_PHOTOS.lego },
      { groupId: 'invalid', primaryPhotoUrl: 'https://invalid-url.com/photo.jpg' },
