  });

  describe('Pull to Refresh', () => {
    it('resets offset and refreshes results', async () => {
      const { getByTestId } = render(
        <DiscoverScreen navigation={mockNavigation as any} route={{} as any} />
      );

      await waitFor(() => {
        expect(searchListings).toHaveBeenCalled();
