        'paused_until',
        'grace_started_at',
        'grace_ends_at',
        'has_used_trial',
        'stripe_payment_method_id',
        'trial_reminder_day_23_sent',
        'trial_reminder_day_28_sent',
        'trial_reminder_day_29_sent',
