      const { data, error } = await supabase
        .from('subscriptions')
        .upsert({
          user_id: testUserId,
          tier_id: tierIdKidsClubPlus,
          status: 'trial',
          trial_start_date: new Date().toISOString(),
          trial_end_date: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
