+    console.log(`  Success rate: ${data.totalProcessed - data.totalFailed}/${data.totalProcessed}`);
+  }, TEST_TIMEOUT * 2); // Double timeout for batch
+
+  test('TC-005: batch-analyze-items respects MAX_CONCURRENCY', async () => {
