  console.log('MISSING_ENV');
  process.exit(0);
}
const s = createClient(url, key);
(async () => {
  const body = {
    items: [
      { groupId: 'group-1', primaryPhotoUrl: 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800' },
