    sellerId: 'test-seller-001'
  };

  const r = await s.functions.invoke('batch-analyze-items', { body });
  console.log(JSON.stringify({
    hasError: !!r.error,
    errorMessage: r.error?.message,
    status: r.error?.context?.status,
    data: r.data
  }, null, 2));
})();
